const C={wave:'#16879b',amber:'#d28a16',purple:'#8260b4',grid:'#d6e1e6',muted:'#78929e'};
const fmt=(n,d=2)=>n.toLocaleString('nb-NO',{maximumFractionDigits:d});
const line=(x1,y1,x2,y2,c=C.muted,more='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" ${more}/>`;
const path=(d,c=C.wave,w=3,more='')=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${more}/>`;
const text=(x,y,s,more='')=>`<text x="${x}" y="${y}" ${more}>${s}</text>`;
const arrow=(x1,y1,x2,y2,c=C.wave)=>{const a=Math.atan2(y2-y1,x2-x1),s=7;return line(x1,y1,x2,y2,c,'stroke-width="2"')+path(`M${x2-s*Math.cos(a-.5)},${y2-s*Math.sin(a-.5)}L${x2},${y2}L${x2-s*Math.cos(a+.5)},${y2-s*Math.sin(a+.5)}`,c,2);};
const graph=(x0,x1,fn)=>{let d='';for(let x=x0;x<=x1;x+=2)d+=(x===x0?'M':'L')+x.toFixed(2)+','+fn(x).toFixed(2);return d;};
const diagram=(id,title,desc,height=280)=>`<svg id="${id}" viewBox="0 0 760 ${height}" preserveAspectRatio="xMidYMid meet" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">${title}</title><desc id="${id}-desc">${desc}</desc></svg>`;
const slider=(id,label,min,max,value,step)=>`<label class="control" for="${id}"><span class="wb-control-head"><span>${label}</span><output id="${id}-value"></output></span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}"></label>`;
const style=`<style>
.wb-scope{--wb-panel:var(--surface-alt,#f1f6f7);--wb-border:var(--border,#d6e1e6);color:var(--ink,#273d4a)}.wb-concept-layout{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:12px 0 14px;align-items:stretch}.wb-definitions{margin:0}.wb-definitions>div{padding:7px 0;border-bottom:1px solid var(--wb-border);display:grid;grid-template-columns:130px 1fr;gap:12px;align-items:baseline}.wb-definitions>div:last-child{border-bottom:0}.wb-definitions dt{font-weight:700;font-size:.92rem}.wb-definitions dd{margin:0;font-size:.9rem;line-height:1.45}.wb-relations{padding:11px 15px;border:1px solid var(--wb-border);border-radius:11px;background:var(--wb-panel)}.wb-equations{font-size:1.25rem;font-weight:700;display:flex;gap:28px;flex-wrap:wrap;margin:1px 0 5px;color:var(--accent,#187b8c)}.wb-relations p{font-size:.86rem;line-height:1.5;margin:4px 0}.wb-relations .wb-example{padding-top:6px;border-top:1px solid var(--wb-border);margin-top:7px}.wb-scope svg{display:block;width:100%;height:auto;max-height:220px;background:var(--wb-panel);border-radius:10px;overflow:hidden}.wb-scope svg text{font:17px system-ui,sans-serif;fill:var(--ink,#273d4a)}.wb-scope svg .wb-small{font-size:15px;fill:var(--muted,#657985)}.wb-scope .wb-controls{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:10px}.wb-scope .wb-controls.wb-two{grid-template-columns:repeat(2,minmax(0,1fr))}.wb-scope .wb-control-head{display:flex;justify-content:space-between;gap:10px;font-size:.88rem}.wb-scope output{font-variant-numeric:tabular-nums;font-weight:650;white-space:nowrap}.wb-scope input[type=range]{width:100%;accent-color:var(--accent,#187b8c);margin-top:5px}.wb-scope .wb-mode-buttons{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:9px}.wb-mode-buttons button,.wb-scope .wb-reset{padding:7px 11px;border:1px solid var(--wb-border);border-radius:8px;background:var(--surface,#fff);color:var(--ink,#273d4a);font:inherit;font-size:.86rem;cursor:pointer}.wb-mode-buttons button[aria-pressed=true]{color:white;background:var(--accent,#187b8c);border-color:var(--accent,#187b8c)}.wb-scope .wb-caption{margin:8px 0 0;font-size:.91rem;line-height:1.5}.wb-scope .model-note{margin:8px 0 0;font-size:.81rem}.wb-scope [hidden]{display:none!important}.wb-scope .wb-reset{align-self:end}.wb-scope .wb-type-note{font-size:.89rem;margin:10px 0}.wb-scope .readout{font-size:.87rem;padding:8px 10px;margin-top:8px}.wb-scope .model{margin:0 auto}.wb-scope .wb-classification{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:14px}.wb-classification p{font-size:.88rem;line-height:1.5;margin:4px 0}.wb-classification strong{font-size:.9rem}@media(max-width:680px){.wb-concept-layout{grid-template-columns:1fr;gap:10px}.wb-definitions>div{grid-template-columns:122px 1fr}.wb-scope .wb-controls,.wb-scope .wb-controls.wb-two{grid-template-columns:1fr}.wb-scope .wb-classification{grid-template-columns:1fr;gap:8px}.wb-scope .wb-controls{gap:7px}.wb-relations{padding:10px 12px}.wb-scope svg{min-height:145px}.wb-mode-buttons button{padding:7px 9px}}
</style>`;

const modes=[['transverse','Tversbølge','wv-transverse'],['longitudinal','Langsbølge','wv-longitudinal']];
const descriptions={
  transverse:'Partiklene svinger på tvers av bølgeretningen. Følg den oransje partikkelen: Den blir i nærheten av samme sted mens bølgemønsteret går mot høyre.',
  longitudinal:'Partiklene svinger langs bølgeretningen. Fortetninger og fortynninger vandrer mot høyre, mens hver partikkel bare svinger fram og tilbake.',
  standing:'To like bølger i motsatt retning danner et stående mønster. Lilla punkter er knuter uten utslag. Mellom dem er buker med størst utslag. Endre antall buker.',
  resonance:'En huske tar opp energi fra dytt i riktig rytme. Still frekvensen nær 0,50 Hz og se at utslaget bygger seg opp. Demping tar hele tiden energi ut av bevegelsen.',
  sound:'Høyttalermembranen setter lufta i svingninger. Fortetninger og fortynninger brer seg til øret og setter trommehinnen i svingninger. Den oransje luftpartikkelen følger ikke lyden hele veien.',
  water:'På dypt vann beveger vannpartiklene seg omtrent i små sirkler. Bølgen går mot høyre, mens partiklene blir nær samme sted. Flytt den oransje partikkelen dypere og se at banen blir mindre.'
};
const modelNotes={
  transverse:'Ideell partikkelmodell. De små prikkene markerer likevektsstillingene.',
  longitudinal:'Ideell langsbølge. Virkelige molekyler har også tilfeldig varmebevegelse, som er utelatt her.',
  standing:'Ideell streng med faste ender, lengde 2 m og bølgefart 2 m/s. Bare mønstre som passer mellom endene, kan bli stående.',
  resonance:'Forenklet, drevet pendel med små vinkler. Dette viser resonans i en svingning; tvers og langs beskriver svingeretningen i en bølge.',
  sound:'Lyden er vist kraftig saktere og med overdrevne partikkelutslag. Trommehinnens form og bevegelse er skjematisk. Høyere frekvens gir lysere tone; større trykkvariasjon gir sterkere lyd.',
  water:'Ideell modell av små overflatebølger på dypt vann. Vannbølger er en kombinasjon av bevegelse langs og på tvers av bølgeretningen. På grunt vann blir banene flatere; svak netto drift er utelatt.'
};

const basics={
  id:'bolger',title:'Bølger og svingninger',kicker:'',summary:'Se sammenhengen mellom amplitude, bølgelengde, frekvens og fart. Utforsk bevegelsen bak lyd, vannbølger og resonans.',
  sections:[
    {title:'Bølgeegenskaper',body:`${style}<div class="wb-scope"><p>En <strong>bølge</strong> er svingninger som brer seg og overfører energi. I mekaniske bølger svinger partiklene lokalt.</p><div class="wb-concept-layout"><dl class="wb-definitions"><div><dt>Amplitude A</dt><dd>Største utslag fra likevekt.</dd></div><div><dt>Bølgelengde λ</dt><dd>Avstand mellom nabotopper.</dd></div><div><dt>Frekvens f<br>Periode T</dt><dd>Antall svingninger per sekund (Hz).<br>Tid per svingning (s).</dd></div></dl><div class="wb-relations"><div class="wb-equations"><span>v = f · λ</span><span>f = 1 / T</span></div><p>Farten v er hvor raskt bølgen brer seg. Ved samme fart betyr høyere frekvens kortere bølgelengde.</p><p class="wb-example"><strong>Eksempel:</strong> v = 4 m/s og f = 2 Hz gir<br>λ = v / f = <strong>2 m</strong> &nbsp; og &nbsp; T = 1 / f = <strong>0,50 s</strong>.</p></div></div><div class="model">${diagram('wv-travel','En løpende tversbølge','En bølge brer seg mot høyre. Den oransje prikken svinger på et fast sted. Endre amplitude, frekvens og fart med gliderne.',300)}<div class="wb-controls">${slider('wv-amplitude','Amplitude A',.2,1.2,.6,.1)}${slider('wv-frequency','Frekvens f',.5,3,1,.1)}${slider('wv-speed','Bølgefart v',2,8,4,.2)}</div><div id="wv-travel-readout" class="readout" aria-live="polite"></div><p class="model-note">Modell av en bølge langs en streng. Større amplitude gir mer energi for samme streng og frekvens.</p></div></div>`},
    {title:'Tversbølger og langsbølger',body:`<div class="wb-scope"><p>I en <strong>tversbølge</strong> svinger partiklene på tvers av bølgeretningen. I en <strong>langsbølge</strong> svinger de langs bølgeretningen. Følg den oransje partikkelen.</p><div class="model"><div class="wb-mode-buttons" role="group" aria-label="Velg bølgetype">${modes.map(([mode,label,id])=>`<button type="button" id="${id}" data-wb-mode="${mode}" aria-pressed="${mode==='transverse'}">${label}</button>`).join('')}</div>${diagram('wv-particles','Tversbølge og langsbølge','Partiklene svinger lokalt mens bølgen brer seg. Bytt bare mellom tvers og langs.')}<div id="wb-particle-controls" class="wb-controls">${slider('wb-particle-frequency','Frekvens i modellen',.3,1.2,.65,.05)}</div><div id="wb-mode-readout" class="readout" aria-live="polite"></div><p id="wv-particles-caption" class="wb-caption">${descriptions.transverse}</p><p id="wb-mode-note" class="model-note">${modelNotes.transverse}</p></div>
<details class="wb-example"><summary>Eksempel på langsbølger: lyd fra høyttaleren til øret</summary><p>${descriptions.sound}</p><div class="model">${diagram('wv-sound','Lyd fra høyttaler til øre','Høyttalermembranen lager fortetninger og fortynninger i lufta som når trommehinnen.',260)}<div id="wb-sound-controls" class="wb-controls">${slider('wb-sound-frequency','Frekvens / tonehøyde',200,1000,500,50)}${slider('wb-sound-amplitude','Trykkvariasjon / lydstyrke',.2,1,.6,.1)}</div><div id="wb-sound-readout" class="readout" aria-live="polite"></div><p class="model-note">${modelNotes.sound}</p></div></details>
<details class="wb-example"><summary>Eksempel på overflatebølger: bevegelsen i vannet</summary><p>${descriptions.water}</p><div class="model">${diagram('wv-water','Vannbølger og partikkelbaner','Vannpartiklene går i omtrent sirkulære baner som blir mindre med dybden.',260)}<div id="wb-water-controls" class="wb-controls">${slider('wb-water-depth','Dybde for oransje partikkel',.1,1.3,.3,.1)}</div><div id="wb-water-readout" class="readout" aria-live="polite"></div><p class="model-note">${modelNotes.water}</p></div></details>
<div class="wb-classification"><div><strong>Mekaniske bølger</strong><p>Trenger et stoff å bre seg i: lyd i luft, bølger på en streng eller i vann.</p></div><div><strong>Elektromagnetiske bølger</strong><p>Svingninger i elektriske og magnetiske felt. Kan bre seg i vakuum.</p></div></div></div>`},
    {title:'Stående bølger',body:`<div class="wb-scope"><p>${descriptions.standing}</p><div class="model">${diagram('wv-standing','Stående bølge på en streng','To bølger i motsatt retning gir knuter og buker.')}<div id="wb-standing-controls" class="wb-controls">${slider('wv-harmonic','Antall buker',1,4,2,1)}</div><div id="wb-standing-readout" class="readout" aria-live="polite"></div><p class="model-note">${modelNotes.standing}</p></div></div>`},
    {title:'Resonans med en huske',body:`<div class="wb-scope"><p>${descriptions.resonance}</p><div class="model">${diagram('wv-resonance','Resonans i en drevet huske','Gjentatte dytt nær egenfrekvensen bygger opp bevegelsen.')}<div id="wb-swing-controls" class="wb-controls">${slider('wb-swing-frequency','Frekvens på dyttene',.3,.8,.5,.01)}${slider('wb-swing-damping','Demping',.06,.25,.08,.01)}<button type="button" id="wb-swing-reset" class="wb-reset">Start huska på nytt</button></div><div id="wb-swing-readout" class="readout" aria-live="polite"></div><p class="model-note">${modelNotes.resonance}</p></div></div>`}
  ],
  terms:[{term:'Amplitude',definition:'Største utslag fra likevektsstillingen.'},{term:'Bølgelengde',definition:'Avstanden mellom to nabopunkter i samme svingefase.'},{term:'Frekvens',definition:'Antall svingninger per sekund, målt i hertz (Hz).'},{term:'Periode',definition:'Tiden for én hel svingning.'},{term:'Bølgefart',definition:'Farten bølgemønsteret brer seg med.'},{term:'Knute',definition:'Punkt uten utslag i en stående bølge.'},{term:'Buk',definition:'Sted med størst utslag i en stående bølge.'},{term:'Resonans',definition:'Stor svingeamplitude ved gjentatt påvirkning nær egenfrekvensen.'}],
  questions:[
    {id:'wv-b1',type:'mcq',level:'Start',prompt:'En lydbølge går gjennom luft. Hva gjør luftpartiklene?',choices:['Følger lyden hele veien fra høyttaleren til øret.','Svinger fram og tilbake omkring sine egne likevektsstillinger.','Står helt stille mens energien passerer.'],correct:1,answer:'Luftpartiklene svinger lokalt. Det er trykkvariasjonen og energien som brer seg gjennom lufta.'},
    {id:'wv-b2',type:'open',level:'Start',prompt:'Tegn en bølge. Marker likevektslinje, bølgetopp, bølgebunn, amplitude og bølgelengde.',answer:'Amplitude måles fra likevektslinjen til en topp eller bunn. Bølgelengden måles mellom to nabotopper eller to nabobunner. Avstanden fra bunn til topp er 2A.'},
    {id:'wv-b3',type:'number',level:'Bruk',prompt:'En bølge har fart 5 m/s og bølgelengde 2 m. Finn frekvensen.',value:2.5,tolerance:.02,unit:'Hz',hint:'Bruk v = f · λ og isoler f.',answer:'f = v / λ = 5 m/s / 2 m = <strong>2,5 Hz</strong>.'},
    {id:'wv-b4',type:'number',level:'Bruk',prompt:'En bølge har frekvens 2,5 Hz. Hva er perioden?',value:.4,tolerance:.005,unit:'s',hint:'Perioden er tiden per svingning.',answer:'T = 1 / f = 1 / 2,5 Hz = <strong>0,40 s</strong>.'},
    {id:'wv-b5',type:'number',level:'Bruk',prompt:'En A-tone har frekvens 440 Hz. Lydfarten er 345 m/s. Finn bølgelengden.',value:345/440,tolerance:.01,unit:'m',answer:'λ = v / f = 345 / 440 m ≈ <strong>0,784 m</strong>.'},
    {id:'wv-b6',type:'number',level:'Bruk',prompt:'Du står på stranda. Bølgene går med fart 4 m/s, og to bølgetopper passerer deg hvert sekund. Hvor langt er det mellom nabotoppene?',value:2,tolerance:.02,unit:'m',answer:'f = 2 Hz. λ = v / f = 4 / 2 m = <strong>2 m</strong>.'},
    {id:'wv-b7',type:'mcq',level:'Start',prompt:'Hva kjennetegner en langsbølge?',choices:['Partiklene svinger vinkelrett på retningen bølgen brer seg.','Partiklene svinger parallelt med retningen bølgen brer seg.','Bølgelengden er alltid større enn én meter.'],correct:1,answer:'I en langsbølge svinger partiklene langs bølgeretningen. Lyd i luft er et eksempel.'},
    {id:'wv-b8',type:'open',level:'Bruk',prompt:'En film viser en eksplosjon langt ute i verdensrommet. Kan astronauten se den? Kan astronauten høre den gjennom vakuum? Forklar.',answer:'Lys er elektromagnetisk stråling og kan gå gjennom vakuum, så eksplosjonen kan sees. Lyd er en mekanisk bølge og trenger et stoff. Den kan derfor ikke høres gjennom vakuum.'},
    {id:'wv-b9',type:'number',level:'Bruk',prompt:'Det går 3,0 s fra du ser et lyn til du hører tordenen. Regn med lydfart 340 m/s og se bort fra lysets reisetid. Hvor langt unna er lynet?',value:1020,tolerance:10,unit:'m',answer:'s = v · t = 340 m/s · 3,0 s = <strong>1020 m</strong>, omtrent 1 km.'},
    {id:'wv-b10',type:'mcq',level:'Bruk',prompt:'Frekvensen dobles mens bølgefarten holdes uendret. Hva skjer med bølgelengden?',choices:['Den dobles.','Den halveres.','Den er uendret.'],correct:1,answer:'λ = v / f. Når frekvensen dobles ved samme bølgefart, halveres bølgelengden.'},
    {id:'wv-b11',type:'open',level:'Bruk',prompt:'Lag to stående bølger på en 2 m lang streng med faste ender: én med én buk og én med to buker. Finn bølgelengden i hvert tilfelle.',answer:'Én buk er en halv bølgelengde: λ = 2L = <strong>4 m</strong>. To buker er én hel bølgelengde: λ = L = <strong>2 m</strong>. Endene er knuter.'},
    {id:'wv-b12',type:'open',level:'Utfordring',prompt:'En elev sier: «Når vi sender mer energi inn i en fjær, må bølgelengden bli kortere.» Vurder påstanden.',answer:'Ikke nødvendigvis. Mer energi kan gi større amplitude. Bølgelengden bestemmes av bølgefart og frekvens gjennom λ = v/f. Holder vi disse uendret, er bølgelengden uendret.'}
  ],
  resources:[{label:'PhET: Bølge på en snor',url:'https://phet.colorado.edu/sims/html/wave-on-a-string/latest/wave-on-a-string_all.html'}],
  mount(root,api){
    const q=id=>root.querySelector('#'+id),val=id=>Number(q(id).value),say=(id,s)=>{if(q(id).textContent!==s)q(id).textContent=s;};
    const layers={};for(const id of ['wv-travel','wv-particles','wv-standing','wv-sound','wv-water','wv-resonance']){const g=document.createElementNS('http://www.w3.org/2000/svg','g');q(id).append(g);layers[id]=g;}
    let particleMode='transverse',angle=.02,angularVelocity=0,swingTime=0,lastTime=null;
    const describe=()=>{
      for(const [m,,id] of modes)q(id).setAttribute('aria-pressed',String(particleMode===m));
      say('wv-particles-caption',descriptions[particleMode]);say('wb-mode-note',modelNotes[particleMode]);
    };
    const update=()=>{
      say('wv-amplitude-value',fmt(val('wv-amplitude'))+' m');say('wv-frequency-value',fmt(val('wv-frequency'))+' Hz');say('wv-speed-value',fmt(val('wv-speed'))+' m/s');
      say('wv-travel-readout',`λ = v / f = ${fmt(val('wv-speed')/val('wv-frequency'))} m · T = 1 / f = ${fmt(1/val('wv-frequency'))} s`);
      say('wb-particle-frequency-value',fmt(val('wb-particle-frequency'))+' Hz');say('wv-harmonic-value',String(val('wv-harmonic')));say('wb-sound-frequency-value',fmt(val('wb-sound-frequency'),0)+' Hz');say('wb-sound-amplitude-value',fmt(val('wb-sound-amplitude')*100,0)+' %');say('wb-water-depth-value',fmt(val('wb-water-depth'))+' m');say('wb-swing-frequency-value',fmt(val('wb-swing-frequency'))+' Hz');say('wb-swing-damping-value',fmt(val('wb-swing-damping')));
      const n=val('wv-harmonic');
      say('wb-standing-readout',`${n} ${n===1?'buk':'buker'} · ${n+1} knuter · λ = ${fmt(4/n)} m · f = ${fmt(n*.5)} Hz`);
      say('wb-swing-readout',`Egenfrekvens: 0,50 Hz · ${Math.abs(val('wb-swing-frequency')-.5)<.055?'Nær resonans: dyttene kan bygge opp store utslag.':'Ulik rytme: mindre effektiv overføring av energi.'}`);
      say('wb-sound-readout',`${fmt(val('wb-sound-frequency'),0)} Hz · relativt lydnivå, uten faktisk lydavspilling.`);
      say('wb-water-readout',`Oransje partikkel: ${fmt(val('wb-water-depth'))} m under likevektsflaten. Banen blir mindre med dybden.`);
      say('wb-mode-readout',`Frekvens: ${fmt(val('wb-particle-frequency'))} Hz · ${particleMode==='transverse'?'Svingning på tvers av bølgeretningen.':'Svingning langs bølgeretningen.'}`);api.repaint();
    };
    for(const [m,,id] of modes)q(id).addEventListener('click',()=>{particleMode=m;describe();update();});
    for(const id of ['wv-amplitude','wv-frequency','wv-speed','wv-harmonic','wb-particle-frequency','wb-sound-frequency','wb-sound-amplitude','wb-water-depth','wb-swing-frequency','wb-swing-damping'])q(id).addEventListener('input',update);
    q('wb-swing-reset').addEventListener('click',()=>{angle=.02;angularVelocity=0;swingTime=0;api.repaint();});
    api.onFrame(t=>{
      const elapsed=lastTime===null?0:Math.max(0,Math.min(.2,t-lastTime));lastTime=t;
      const A=val('wv-amplitude'),f=val('wv-frequency'),v=val('wv-speed'),lambda=v/f,scale=620/16;
      const y=x=>165-A*64*Math.sin(2*Math.PI*((x-70)/(scale*lambda)-f*t));
      let grid='';for(const m of [0,4,8,12,16]){const x=70+m*scale;grid+=line(x,82,x,244,C.grid)+text(x,263,String(m),'text-anchor="middle" class="wb-small"');}
      layers['wv-travel'].innerHTML=`${grid}${line(70,165,690,165,'#9bb0ba')}${line(70,82,70,244)}${path(graph(70,690,y),C.wave,3.5)}${line(341,83,341,244,C.amber,'stroke-dasharray="3 5" opacity=".5"')}<circle cx="341" cy="${y(341)}" r="8" fill="${C.amber}" stroke="white" stroke-width="2"/>${line(45,165-A*64,45,165,C.amber,'stroke-width="2"')}${text(30,169-A*32,'A','text-anchor="middle"')}${line(70,42,70+lambda*scale,42,C.purple,'stroke-width="2"')}${line(70,36,70,48,C.purple)}${line(70+lambda*scale,36,70+lambda*scale,48,C.purple)}${text(70+lambda*scale/2,31,'λ','text-anchor="middle"')}${text(747,263,'x (m)','text-anchor="end" class="wb-small"')}${text(80,155,'Likevekt','class="wb-small"')}${arrow(530,283,678,283)}${text(515,288,'Bølgeretning','text-anchor="end" class="wb-small"')}`;
      for(const [sceneMode,svgId] of [['particles','wv-particles'],['standing','wv-standing'],['sound','wv-sound'],['water','wv-water'],['resonance','wv-resonance']]){
      const mode=sceneMode==='particles'?particleMode:sceneMode;
      let scene='';
      if(mode==='transverse'||mode==='longitudinal'){
        const transverse=mode==='transverse',frequency=val('wb-particle-frequency');let dots='';
        for(let i=0;i<16;i++){let x0=80+i*40,ph=2*Math.PI*(i/7-frequency*t),x=transverse?x0:x0+16*Math.sin(ph),yy=transverse?140-52*Math.sin(ph):140;dots+=`<circle cx="${x0}" cy="140" r="2.5" fill="#b3c5cc"/>${i===7?line(transverse?x0:x0-22,transverse?78:140,transverse?x0:x0+22,transverse?202:140,C.amber,'stroke-dasharray="3 4"'):''}<circle cx="${x}" cy="${yy}" r="${i===7?10:7}" fill="${i===7?C.amber:C.wave}"/>`;}
        scene=`${arrow(275,50,490,50)}${text(380,30,'Bølgeretning','text-anchor="middle"')}${dots}${text(380,260,'Oransje partikkel: lokal svingning','text-anchor="middle" class="wb-small"')}`;
      } else if(mode==='standing'){
        const n=val('wv-harmonic'),sy=x=>145-62*Math.sin(n*Math.PI*(x-60)/640)*Math.cos(2*Math.PI*n*.5*t);let nodes='',envelopes='';
        for(let k=0;k<=n;k++)nodes+=`<circle cx="${60+k*640/n}" cy="145" r="4.5" fill="${C.purple}"/>`;
        for(const sign of [-1,1])envelopes+=path(graph(60,700,x=>145+sign*62*Math.sin(n*Math.PI*(x-60)/640)),C.grid,1.5,'stroke-dasharray="4 4"');
        scene=`${text(62,30,'Faste ender','class="wb-small"')}${text(630,30,'● knute','text-anchor="middle" class="wb-small"')}${line(60,145,700,145,C.grid)}${line(54,72,54,218,C.muted,'stroke-width="5"')}${line(706,72,706,218,C.muted,'stroke-width="5"')}${envelopes}${path(graph(60,700,sy),C.wave,3.5)}${nodes}${line(60,247,700,247,C.muted)}${text(380,269,'Strenglengde L = 2 m','text-anchor="middle" class="wb-small"')}`;
      } else if(mode==='sound'){
        const frequency=val('wb-sound-frequency'),strength=val('wb-sound-amplitude'),wavelength=190*500/frequency,omega=2*Math.PI*frequency/625,amp=12*500/frequency*strength;
        const ph=x=>2*Math.PI*(x-142)/wavelength-omega*t,membraneX=142+amp*Math.sin(ph(142)),drumX=647+amp*.7*Math.sin(ph(605));let air='',pressure='';
        for(let row=0;row<4;row++)for(let i=0;i<30;i++){const x0=168+i*14,xx=x0+amp*Math.sin(ph(x0)),isMark=row===1&&i===13;air+=`<circle cx="${xx}" cy="${88+row*17}" r="${isMark?5.5:2.8}" fill="${isMark?C.amber:C.wave}" opacity="${isMark?1:.75}"/>`;}
        for(let i=0;i<104;i++){let x=164+i*4,p=-Math.cos(ph(x))*strength;pressure+=`<rect x="${x}" y="174" width="4.2" height="12" fill="${p>=0?'#ce6d57':'#4b88ae'}" opacity="${.13+.72*Math.abs(p)}"/>`;}
        scene=`${text(94,28,'Høyttaler','text-anchor="middle"')}${text(375,28,'Luft: fortetning og fortynning','text-anchor="middle"')}${text(674,28,'Øre','text-anchor="middle"')}<rect x="45" y="72" width="52" height="79" rx="8" fill="#708b98"/>${path('M97,88L131,69L131,155L97,136Z','#708b98',2,'fill="#b4c9d3"')}${line(membraneX,73,membraneX,151,C.purple,'stroke-width="5"')}${air}${path('M694,67C731,71 721,115 704,128C697,136 704,159 682,163C666,163 662,151 668,141C675,128 688,126 684,114C681,105 668,108 669,121',C.muted,4)}${line(drumX,93,drumX,138,C.purple,'stroke-width="4"')}${line(607,102,drumX,102,C.grid)}${line(607,132,drumX,132,C.grid)}${pressure}${text(375,207,'Trykk: rød = overtrykk · blå = undertrykk','text-anchor="middle" class="wb-small"')}${text(647,188,'Trommehinne','text-anchor="middle" class="wb-small"')}${arrow(230,53,527,53,C.wave)}`;
      } else if(mode==='water'){
        const k=2*Math.PI/260,omega=2*Math.PI*.55,base=79,amplitude=18,depth=val('wb-water-depth'),trackedY=base+depth*70,orbit=amplitude*Math.exp(-k*(trackedY-base)),trackedPhase=k*(380-30)-omega*t;let surface='',particles='';
        for(let x=15;x<=745;x+=3){let p=k*(x-30)-omega*t,xx=x+amplitude*Math.cos(p),yy=base-amplitude*Math.sin(p);surface+=(x===15?'M':'L')+xx+','+yy;}
        for(const yy of [105,143,180])for(let x0=65;x0<=710;x0+=65){let a=amplitude*Math.exp(-k*(yy-base)),p=k*(x0-30)-omega*t;particles+=`<circle cx="${x0+a*Math.cos(p)}" cy="${yy-a*Math.sin(p)}" r="3.2" fill="${C.wave}" opacity=".67"/>`;}
        scene=`<rect x="15" y="79" width="730" height="127" rx="4" fill="#e1f0f5"/>${path(surface+'L760,206L0,206Z','#c7e4ef',1,'fill="#c7e4ef"')}${path(surface,C.wave,3)}${particles}${line(380,base,380,trackedY,C.amber,'stroke-dasharray="3 5" opacity=".5"')}<circle cx="380" cy="${trackedY}" r="${orbit}" fill="none" stroke="${C.amber}" stroke-width="1.5" stroke-dasharray="3 3"/><circle cx="${380+orbit*Math.cos(trackedPhase)}" cy="${trackedY-orbit*Math.sin(trackedPhase)}" r="6" fill="${C.amber}" stroke="white" stroke-width="1.5"/>${arrow(480,35,676,35)}${text(465,39,'Bølgeretning','text-anchor="end" class="wb-small"')}${text(42,197,'Partikkelbanene avtar med dybden','class="wb-small"')}`;
      } else {
        const naturalOmega=Math.PI,damping=val('wb-swing-damping'),drive=val('wb-swing-frequency'),torque=.55;
        const steps=Math.max(1,Math.ceil(elapsed/.008)),dt=elapsed/steps;
        for(let i=0;i<steps;i++){const acceleration=torque*Math.sin(2*Math.PI*drive*swingTime)-2*damping*naturalOmega*angularVelocity-naturalOmega**2*angle;angularVelocity+=acceleration*dt;angle+=angularVelocity*dt;swingTime+=dt;}
        const bobX=300+140*Math.sin(angle),bobY=35+140*Math.cos(angle),force=Math.sin(2*Math.PI*drive*swingTime),energy=Math.min(1,(angularVelocity**2+naturalOmega**2*angle**2)/(naturalOmega**2*.5**2));
        scene=`${line(209,30,391,30,C.muted,'stroke-width="6"')}${line(300,35,300,175,C.grid,'stroke-dasharray="4 4"')}${line(300,35,bobX,bobY,C.wave,'stroke-width="3"')}<circle cx="300" cy="35" r="4" fill="${C.muted}"/>${line(bobX-18,bobY,bobX+18,bobY,C.wave,'stroke-width="6"')}<circle cx="${bobX}" cy="${bobY-28}" r="8" fill="${C.amber}"/>${line(bobX,bobY-20,bobX,bobY-3,C.amber,'stroke-width="5"')}${line(bobX,bobY-3,bobX+12,bobY+8,C.amber,'stroke-width="4"')}${text(300,211,'Huska: egenfrekvens 0,50 Hz','text-anchor="middle" class="wb-small"')}${text(575,59,'Gjentatte dytt','text-anchor="middle"')}${Math.abs(force)>.03?arrow(575-34*force,93,575+34*force,93,C.amber):''}${text(575,133,'Energi i bevegelsen','text-anchor="middle" class="wb-small"')}<rect x="496" y="148" width="158" height="12" rx="5" fill="${C.grid}"/><rect x="496" y="148" width="${158*energy}" height="12" rx="5" fill="${C.wave}"/>${text(575,187,'Demping begrenser utslaget','text-anchor="middle" class="wb-small"')}`;
      }
      layers[svgId].innerHTML=scene;
      if(sceneMode==='sound'||sceneMode==='water'||sceneMode==='resonance')layers[svgId].setAttribute('transform','translate(0 22)');
      }
    });describe();update();
  }
};

export const topics=[basics];
